<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli')exit(1);
require dirname(__DIR__).'/app/bootstrap.php';$pdo=App\Support\Database::connect();
if(getenv('DB_HOST')!=='127.0.0.1'||getenv('DB_PORT')!=='3309'||$pdo->query('SELECT DATABASE()')->fetchColumn()!=='dharma_sales_phase1')throw new RuntimeException('Exact application target required.');
$queries=[
            'Invoice discount snapshots / allocations'=>"SELECT d.invoice_id FROM invoice_discount_snapshots d JOIN invoices i ON i.id=d.invoice_id LEFT JOIN (SELECT invoice_id,SUM(manual_discount_amount) allocated FROM invoice_items GROUP BY invoice_id) l ON l.invoice_id=i.id WHERE d.discount_amount<>i.manual_discount_total OR d.discount_amount<>COALESCE(l.allocated,0) OR d.discountable_subtotal<>i.subtotal-i.automatic_discount_total OR d.discount_amount<>ROUND(d.discountable_subtotal*d.percent_rate/100,2)",
 'Invoice lines reconcile with totals'=>"SELECT i.id FROM invoices i JOIN online_invoice_details d ON d.invoice_id=i.id LEFT JOIN (SELECT invoice_id,SUM(gross_amount) gross,SUM(discount_amount) discount,SUM(line_total) net FROM invoice_items GROUP BY invoice_id) l ON l.invoice_id=i.id WHERE l.gross IS NULL OR i.subtotal<>l.gross OR i.discount_total<>l.discount OR i.grand_total<>l.net",
 'Posted cash allocations reconcile'=>"SELECT r.request_id FROM invoice_receipts r LEFT JOIN payments p ON p.id=r.payment_id LEFT JOIN payment_allocations a ON a.payment_id=r.payment_id AND a.invoice_id=r.invoice_id WHERE r.applied_amount>0 AND (p.id IS NULL OR a.payment_id IS NULL OR p.amount<>r.applied_amount OR a.amount<>r.applied_amount OR p.status<>'POSTED')",
 'Payments never exceed invoice total'=>"SELECT i.id FROM invoices i JOIN payment_allocations a ON a.invoice_id=i.id JOIN payments p ON p.id=a.payment_id WHERE p.status='POSTED' GROUP BY i.id,i.grand_total HAVING SUM(a.amount)>i.grand_total",
 'Sold stock matches paid plus free units'=>"SELECT l.id FROM invoice_items l JOIN online_invoice_details d ON d.invoice_id=l.invoice_id LEFT JOIN inventory_transactions t ON t.invoice_id=l.invoice_id AND t.type='SALE' LEFT JOIN inventory_movements m ON m.transaction_id=t.id AND m.product_id=l.product_id AND m.location_id=d.source_location_id WHERE t.id IS NULL OR m.id IS NULL OR m.quantity_delta<>-(l.quantity+l.free_quantity)",
 'Void stock is reversed exactly once'=>"SELECT l.id FROM invoice_voids v JOIN invoice_items l ON l.invoice_id=v.invoice_id JOIN online_invoice_details d ON d.invoice_id=v.invoice_id LEFT JOIN inventory_transactions t ON t.id=v.reversal_transaction_id LEFT JOIN inventory_movements m ON m.transaction_id=t.id AND m.product_id=l.product_id AND m.location_id=d.source_location_id WHERE t.reverses_transaction_id<>v.invoice_id OR m.id IS NULL OR m.quantity_delta<>l.quantity+l.free_quantity",
 'Refund liability equals immutable received payments'=>"SELECT v.invoice_id FROM invoice_voids v JOIN invoices i ON i.id=v.invoice_id LEFT JOIN (SELECT a.invoice_id,SUM(a.amount) paid FROM payment_allocations a JOIN payments p ON p.id=a.payment_id WHERE p.status='POSTED' GROUP BY a.invoice_id) p ON p.invoice_id=v.invoice_id WHERE v.refund_due<>COALESCE(p.paid,0) OR v.cancelled_outstanding+v.refund_due<>i.grand_total",
 'Lifetime counters exceed all allocated invoice numbers'=>"SELECT i.rep_id FROM invoices i LEFT JOIN invoice_sequence_counters c ON c.rep_id=i.rep_id GROUP BY i.rep_id,c.next_sequence HAVING c.next_sequence IS NULL OR c.next_sequence<=MAX(i.sequence_number)"
];
foreach($queries as $label=>$sql){if($pdo->query($sql)->fetch())throw new RuntimeException($label.' FAILED');echo $label." passed.\n";}
$admin=$pdo->query("SELECT id FROM users WHERE role='ADMIN' AND is_active=1 ORDER BY id LIMIT 1")->fetch();
if(!$admin||(new App\Services\ProductStock($pdo))->reconciliation($admin)!==[]||(new App\Services\RepresentativeStock($pdo))->reconciliation($admin)!==[])throw new RuntimeException('Stock reconciliation failed.');
echo 'Warehouse and representative ledger reconciliation passed. Issued invoices: '.$pdo->query('SELECT COUNT(*) FROM online_invoice_details')->fetchColumn().'; refunds due: '.$pdo->query('SELECT COALESCE(SUM(refund_due),0.00) FROM invoice_voids')->fetchColumn()." LKR.\n";
